// path : tags du plus profond (nœud cliqué) vers la racine, ex. ['span','button','li','ul'].
// Renvoie le premier tag == tag (le plus proche du clic), sinon null. Comme closest().
export function delegatedMatch(path, tag) {
  // BUG : renvoie toujours le nœud cliqué, sans chercher l'ancêtre correspondant.
  return path[0];
}

